 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ChangePage_onclick = async function(e){
    try {
        await scwin.changePage(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil51400.btn_ChangePage_onclick' }); }
};

