///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name selectBox
 * @description select Box 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.selectBox = function (ver) {
    const date = new Date();
    let year;
    let month;
    document.write("<option value='000000'>--- 선택 ---</option>");
    for (let i = 1; i < 13; i++) {
        if (ver === '0') {
            year = date.getFullYear();
            month = (date.getMonth() + 1) + "";
            if (month.length === 1) {
                month = "0" + month;
            }
            document.write("<option value='" + (year + "" + month) + "'>" + year + "년" + month + "월" + "</option>");
            date.setMonth(date.getMonth() + 1);
        } else {
            if (ver === '0') {
                document.write("<option value='" + i + "'>" + i + "월" + "</option>");
            } else {
                if (i < 7) {
                    if (i === 1) {
                        date.setFullYear(date.getFullYear() - 5);
                    }
                    year = date.getFullYear();
                    document.write("<option value='" + year + "'>" + year + "년</option>");
                    date.setFullYear(date.getFullYear() + 1);
                } else {
                    return;
                }
            }
        }
    }
};

/**
 * @method
 * @name changePage
 * @description change Page 처리
 * @param {*} pageIndex pageIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changePage = async function (pageIndex) {
    //    if( eval(form.nowPage.value) <= eval(form.billLstSaveStatCd.value) || eval(pageIndex) <= (eval(form.billLstSaveStatCd.value) + 1)) {
    if( (pageIndex) <= ((form.billLstSaveStatCd.value) + 1)) {

        form.nowPage.value = pageIndex ;

        //        window.status=pageIndex + "page로 이동중" ;
        if( (pageIndex) < 5 ) {
            form.action = '/list/prelist.do';
            form.method.value = 'prelistSearch';
        } else {
            form.action = '/list/prelistEtc.do';
            form.method.value = 'prelistSearchEtc';
        }
        await moveUrl('/list/prelist.do', {});

    } else {
        await $c.win.alert("현재페이지의 항목들을 저장후에 다음 페이지로 이동할수 있습니다.");
        return ;
    }

};

/**
 * @method
 * @name majChange
 * @description maj Change 처리
 * @returns {void}
 * @hidden N
 */
scwin.majChange = function () {
    // 최대주주 합계주식수
    $c.util.getComponent('ipt_sumLgShr').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_lgshrhdCmstkShrs').getValue()) + scwin.rmComma($c.util.getComponent('ipt_lgshrhdPrefstkShrs').getValue())));

    // 최대주주 관계자 합계주식수
    form.sumRelShr.value = $c.num.formatNumber(
        scwin.rmComma(form.lgshrhdRelprnCmstkShrs.value) + scwin.rmComma(form.lgshrhdRelprnPrefstkShrs.value));

    // 최대주주 보통주 소계  주식수
    form.sumSubCmn.value = $c.num.formatNumber(
        scwin.rmComma($c.util.getComponent('ipt_lgshrhdCmstkShrs').getValue()) + scwin.rmComma(form.lgshrhdRelprnCmstkShrs.value));

    // 최대주주 우선주 소계 주식수
    form.sumSubPref.value = $c.num.formatNumber(
        scwin.rmComma($c.util.getComponent('ipt_lgshrhdPrefstkShrs').getValue()) + scwin.rmComma(form.lgshrhdRelprnPrefstkShrs.value));

    // 최대주주 보통+우선주 소계 주식수
    $c.util.getComponent('ipt_sumSubTot').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_sumLgShr').getValue()) + scwin.rmComma(form.sumRelShr.value)));

    fn_TotalChange();

};

